// src/pages/Todo/Todo.js - Головний компонент сторінки Todo
import React, { useState, useEffect, useCallback } from 'react';
import TodoList from './TodoList';
import TodoForm from './TodoForm';
import { useTheme } from '../../contexts/ThemeContext';
import { getTodos, createTodo, updateTodo, deleteTodoApi } from './api'; // Імпортуємо функції API
import './styles.css'; // Імпортуємо стилі для Todo

const TodoPage = () => {
    const { theme } = useTheme();
    const [todos, setTodos] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    const fetchAllTodos = useCallback(async () => {
        setLoading(true);
        setError(null);
        try {
            const data = await getTodos();
            setTodos(data.slice(0, 10)); // Обмежуємо до 10 завдань для JSONPlaceholder
        } catch (err) {
            console.error('Помилка отримання списків завдань:', err);
            setError('Не вдалося завантажити завдання. Спробуйте ще раз.');
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchAllTodos();
    }, [fetchAllTodos]);

    const handleAddTodo = async (title) => {
        try {
            const newTodo = await createTodo(title);
            // JSONPlaceholder завжди повертає ID=201 для POST, ми можемо симулювати унікальний ID
            // або просто додати його як є для прикладу
            setTodos(prevTodos => [{ ...newTodo, id: Date.now() }, ...prevTodos]);
        } catch (err) {
            console.error('Помилка додавання завдання:', err);
            alert('Не вдалося додати завдання. Спробуйте ще раз.');
        }
    };

    const handleToggleTodo = async (id, completed) => {
        try {
            // Оптимістичне оновлення UI
            setTodos(prevTodos =>
                prevTodos.map(todo =>
                    todo.id === id ? { ...todo, completed: completed } : todo
                )
            );
            await updateTodo(id, { completed });
        } catch (err) {
            console.error('Помилка перемикання статусу завдання:', err);
            alert('Не вдалося перемкнути статус завдання. Спробуйте ще раз.');
            // Відкат у випадку помилки
            setTodos(prevTodos =>
                prevTodos.map(todo =>
                    todo.id === id ? { ...todo, completed: !completed } : todo
                )
            );
        }
    };

    const handleEditTodo = async (id, newTitle) => {
        try {
            // Оптимістичне оновлення UI
            setTodos(prevTodos =>
                prevTodos.map(todo =>
                    todo.id === id ? { ...todo, title: newTitle } : todo
                )
            );
            await updateTodo(id, { title: newTitle });
        } catch (err) {
            console.error('Помилка редагування завдання:', err);
            alert('Не вдалося відредагувати завдання. Спробуйте ще раз.');
            // У випадку помилки, потрібно буде зробити повторний fetch або відкат
            fetchAllTodos(); // Простіший відкат для прикладу
        }
    };

    const handleDeleteTodo = async (id) => {
        try {
            // Оптимістичне видалення з UI
            setTodos(prevTodos => prevTodos.filter(todo => todo.id !== id));
            await deleteTodoApi(id);
        } catch (err) {
            console.error('Помилка видалення завдання:', err);
            alert('Не вдалося видалити завдання. Спробуйте ще раз.');
            // Відкат у випадку помилки
            fetchAllTodos(); // Простіший відкат для прикладу
        }
    };

    return (
        <div className={`page-content todo-page ${theme}`}>
            <h2 className={`todo-title-page ${theme}`}>Список Завдань (Todo List)</h2>
            <TodoForm onAdd={handleAddTodo} />
            {loading && <p className={`loading-message ${theme}`}>Завантаження завдань...</p>}
            {error && <p className={`error-message ${theme}`}>{error}</p>}
            {!loading && !error && (
                <TodoList
                    todos={todos}
                    onToggle={handleToggleTodo}
                    onEdit={handleEditTodo}
                    onDelete={handleDeleteTodo}
                />
            )}
        </div>
    );
};

export default TodoPage;
